def test_pm01_compositional_sums_match():
    receipts = [{'amount': 3}, {'amount': 7}]
    ledger = {'entries': [3, 7]}
    assert sum(r['amount'] for r in receipts) == sum(ledger['entries']) == 10

def test_pm01_negative_unknown_currency_rejected():
    KNOWN = {'USD', 'EUR'}
    def check(cur):
        if cur not in KNOWN:
            raise ValueError('unknown currency')
        return True
    assert check('USD') is True
    try:
        check('XXX')
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_pm01_boundary_zero_amount_rejected():
    def check(amount):
        if amount <= 0:
            raise ValueError('non-positive amount')
        return True
    assert check(1) is True
    try:
        check(0)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_pm02_compositional_partitions():
    def part_a(items):
        return [x for x in items if x % 2 == 0]
    def part_b(items):
        return [x for x in items if x % 2 == 1]
    items = [1, 2, 3, 4]
    assert sorted(part_a(items) + part_b(items)) == [1, 2, 3, 4]

def test_pm02_negative_overlap_rejected():
    def check_disjoint(a, b):
        if set(a) & set(b):
            raise ValueError('overlap')
        return True
    assert check_disjoint([1], [2]) is True
    try:
        check_disjoint([1], [1])
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_pm02_boundary_empty_partition():
    def part_a(items):
        return [x for x in items if x % 2 == 0]
    assert part_a([]) == []
